def formula_svg() -> str:
    labels = ['TRADITION','EDUCATION','TECHNOLOGY','MIGRATION','WORK','FAITH','COMMUNITY','CITIZENSHIP']
    nodes = ''.join(f'<circle cx="300" cy="180" r="{38 + i*21}" fill="none" stroke="{("#2E8B57" if i%3==0 else "#B59654" if i%3==1 else "#7894A8")}" stroke-opacity=".55"/><text x="300" y="{145-i*2}" text-anchor="middle" font-family="Arial" font-size="{10 if i<6 else 9}" fill="#F5F0E6">{x}</text>' for i,x in enumerate(labels))
    return f'''<figure class="logic-diagram" aria-labelledby="formula-caption"><svg viewBox="0 0 620 380" role="img" aria-labelledby="formula-title formula-desc" xmlns="http://www.w3.org/2000/svg"><title id="formula-title">The modern Orakzai formula</title><desc id="formula-desc">A layered conceptual diagram combines tradition, education, technology, migration, work, faith, community, and citizenship into a modern Orakzai framework. It is not a universal identity formula.</desc><rect x="12" y="12" width="596" height="356" rx="10" fill="#101510" stroke="#B59654" stroke-opacity=".42"/><circle cx="300" cy="180" r="34" fill="#3C3020" stroke="#B59654"/><text x="300" y="184" text-anchor="middle" font-family="Arial" font-size="12" fill="#F5F0E6" font-weight="700">MODERN</text>{nodes}<text x="300" y="345" text-anchor="middle" font-family="Arial" font-size="10" fill="#B59654" letter-spacing="1.2">COEXISTENCE — NOT REPLACEMENT</text></svg><figcaption id="formula-caption" class="diagram-caption">Modern Orakzai identity can connect inherited roots with education, work, technology, mobility, community, and civic responsibility.</figcaption></figure>'''


def milestone_svg() -> str:
    points=[('PAGE 1','ANCESTRY'),('PAGE 25','LANGUAGE + CULTURE'),('PAGE 50','LIFE + COMMUNITY'),('PAGE 75','HISTORY + FRONTIER'),('PAGE 100','THE MODERN ORAKZAI')]
    rows=''.join(f'<circle cx="80" cy="{55+i*60}" r="12" fill="#3C3020" stroke="#B59654"/><text x="80" y="{59+i*60}" text-anchor="middle" font-family="Arial" font-size="8" fill="#F5F0E6">{i+1}</text><path d="M104 {55+i*60} H180" stroke="#B59654"/><text x="200" y="{50+i*60}" font-family="Arial" font-size="11" fill="#B59654">{p}</text><text x="200" y="{67+i*60}" font-family="Arial" font-size="10" fill="#F5F0E6">{x}</text>' for i,(p,x) in enumerate(points))
    return f'''<figure class="logic-diagram" aria-labelledby="milestone-caption"><svg viewBox="0 0 620 370" role="img" aria-labelledby="milestone-title milestone-desc" xmlns="http://www.w3.org/2000/svg"><title id="milestone-title">One hundred page milestone</title><desc id="milestone-desc">A five-point timeline connects Page 1, Page 25, Page 50, Page 75, and Page 100 to major thematic stages of the book. Page 100 is a milestone, not the end of the book.</desc><rect x="12" y="12" width="596" height="346" rx="10" fill="#101510" stroke="#B59654" stroke-opacity=".42"/><path d="M80 55 V295" stroke="#2E8B57" stroke-width="2"/>{rows}<text x="310" y="337" text-anchor="middle" font-family="Arial" font-size="10" fill="#B59654" letter-spacing="1.3">100 PAGES · ONE PEOPLE · MANY GENERATIONS · AN UNFINISHED STORY</text></svg><figcaption id="milestone-caption" class="diagram-caption">Page 100 marks a transition into the book’s next section; it is not presented as the end of the full 200-page project.</figcaption></figure>'''


def atlas_html() -> str:
    cards='\n'.join(svg_card(*row,i) for i,row in enumerate(GRAPHICS,1))
    return f'<section class="logic-atlas" aria-labelledby="atlas-title"><h3 id="atlas-title" class="section-label">Logic Atlas: The Modern Orakzai</h3><p>These {len(GRAPHICS)} original SVG graphics translate the page’s reasoning into compact, printable structures. They distinguish documented contemporary evidence from emerging possibilities and do not turn one project, one seminar, or one statistic into a district-wide claim.</p><div class="atlas-grid">{cards}</div></section>'

